    <script>
        // ---------------------------------
        // 📝 DADOS DO FORMULÁRIO (EDITÁVEL)
        // ---------------------------------
        const questions = [
            {
                question: "O QUANTO VOCÊ ESTÁ CONTENTE COM SEU FÍSICO HOJE?",
                options: ["MUITO CONTENTE 😁", "PODERIA MELHORAR 😊", "NADA CONTENTE 😑", "MUITO MAL 😔"]
            },
            {
                question: "QUAL SEU OBJETIVO PRINCIPAL COM A MUDANÇA?",
                options: ["EMAGRECIMENTO RÁPIDO 🏃", "MAIS ENERGIA DIÁRIA ⚡", "MELHORAR POSTURA 🧍", "AUMENTAR AUTOESTIMA 💖"]
            },
            {
                question: "QUANTO TEMPO VOCÊ JÁ TENTOU MUDAR?",
                options: ["MENOS 1 MÊS ⏳", "1 A 6 MESES 🗓️", "MAIS DE 6 MESES 😥", "NUNCA TENTEI 🙅"]
            },
            {
                question: "O QUE TE IMPEDE DE COMEÇAR AGORA?",
                options: ["Falta de tempo ⏰", "Dúvidas sobre o método 🤔", "Falta de motivação 💪", "Preço 💰"]
            }
        ];

        // ---------------------------------
        // ⚙️ LÓGICA DO FORMULÁRIO
        // ---------------------------------
        let currentStep = 0;
        const quizArea = document.getElementById('quizArea');
        const finalScreen = document.getElementById('finalScreen');
        const questionDisplay = document.getElementById('questionDisplay');
        const optionsContainer = document.getElementById('optionsContainer');
        const nextBtn = document.getElementById('nextBtn');

        function renderStep() {
            if (currentStep < questions.length) {
                // Renderiza a pergunta atual
                const qData = questions[currentStep];
                questionDisplay.textContent = qData.question;

                // Limpa e renderiza as opções
                optionsContainer.innerHTML = '';
                qData.options.forEach(optionText => {
                    const optionDiv = document.createElement('div');
                    optionDiv.className = 'alternative';
                    optionDiv.textContent = optionText;
                    // Adiciona o listener de clique
                    optionDiv.addEventListener('click', () => handleAnswer(optionText));
                    optionsContainer.appendChild(optionDiv);
                });

                // O botão 'Próxima' só deve aparecer DEPOIS de uma resposta ser clicada
                nextBtn.style.display = 'none';

            } else {
                // Fim do quiz - Mostra a tela final
                quizArea.style.display = 'none';
                finalScreen.style.display = 'block';
            }
        }

        function handleAnswer(selectedOption) {
