        nextBtn.addEventListener('click', () => {
            currentStep++;
            // Limpa o estado da tela anterior
            optionsContainer.innerHTML = '';
            document.querySelectorAll('.alternative').forEach(el => el.style.pointerEvents = 'auto');

            renderStep();
        });

        // Inicia o processo
        renderStep();

