    <script>
        document.getElementById('btnCalcular').addEventListener('click', calcularCircuito);

        function calcularCircuito() {
            // 1. Coletar valores dos inputs
            const V_in = parseFloat(document.getElementById('valorV').value) || 0;
            const I_in = parseFloat(document.getElementById('valorI').value) || 0;
            const R_in = parseFloat(document.getElementById('valorR').value) || 0;

            // 2. Coletar o campo que o usuário quer descobrir
            const campoDesejado = document.getElementById('campoDesconhecido').value;
            const resultadoDiv = document.getElementById('resultado');

            let resultado = null;
            let sucesso = true;

            // 3. Validação: Garantir que pelo menos 2 valores sejam fornecidos (e não sejam zero)
            const valoresFornecidos = [V_in, I_in, R_in].filter(v => v !== 0).length;

            if (valoresFornecidos < 2) {
                resultadoDiv.innerHTML = '<div class="alert alert-warning">⚠️ Por favor, insira pelo menos DOIS valores (V, I ou R) para calcular o terceiro.</div>';
                return;
            }

            // 4. Lógica de cálculo baseada no campo desejado
            switch (campoDesejado) {
                case 'V': // Calcular Tensão (V = I * R)
